package ec.edu.ucacue.odontocare.reporting;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;
import ec.edu.ucacue.odontocare.shared.domain.AuditLog;
import ec.edu.ucacue.odontocare.shared.infrastructure.AuditLogRepository;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
@RestController@RequestMapping("/api/clinical-records/{recordId}/report.pdf")@Tag(name="Reporte clínico")@SecurityRequirement(name="bearerAuth")public class ClinicalPdfController{private final ClinicalPdfService service;private final AuditLogRepository auditLogRepository;public ClinicalPdfController(ClinicalPdfService service, AuditLogRepository auditLogRepository){this.service=service;this.auditLogRepository=auditLogRepository;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE,produces=MediaType.APPLICATION_PDF_VALUE)@Operation(summary="Generar PDF consolidado de la historia clínica")public ResponseEntity<byte[]> generate(@PathVariable Long recordId,@RequestPart(name="odontogram",required=false)MultipartFile odontogram,@AuthenticationPrincipal ec.edu.ucacue.odontocare.auth.application.UserPrincipal userPrincipal){auditLogRepository.save(new AuditLog(userPrincipal.id(), "REPORT_GENERATED", "ClinicalRecord", recordId, "{}"));byte[] pdf=service.generate(recordId,odontogram);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=historia-clinica-"+recordId+".pdf").contentType(MediaType.APPLICATION_PDF).contentLength(pdf.length).body(pdf);}}
